Here's a Python script that does this. It reads the EXIF capture date (`DateTimeOriginal`) and falls back to other EXIF date fields, then the file's modification time for photos without EXIF. It defaults to a dry run, so you can check the proposed names before anything is touched.

```python
#!/usr/bin/env python3
"""
rename_photos_by_date.py

Rename photos to the date they were taken:
    IMG_1234.JPG  ->  2024-05-12_001.jpg

Date source: EXIF DateTimeOriginal, then DateTimeDigitized, then DateTime,
then the file's modification time.

Usage:
    python rename_photos_by_date.py .                 # dry run (safe)
    python rename_photos_by_date.py . --apply         # actually rename
    python rename_photos_by_date.py ~/Pictures/2024 --apply -r
"""

import argparse
import re
import sys
from datetime import datetime
from pathlib import Path

try:
    from PIL import Image
except ImportError:
    sys.exit("This script needs Pillow. Install it with:  pip install Pillow")

try:  # optional, enables iPhone .heic files
    import pillow_heif
    pillow_heif.register_heif_opener()
except ImportError:
    pass

PHOTO_EXTENSIONS = {".jpg", ".jpeg", ".png", ".heic", ".heif", ".tif", ".tiff", ".webp"}
ALREADY_RENAMED = re.compile(r"^\d{4}-\d{2}-\d{2}_\d{3,}$")
EXIF_IFD = 0x8769
TAG_DATE_TIME_ORIGINAL = 36867
TAG_DATE_TIME_DIGITIZED = 36868
TAG_DATE_TIME = 306


def _parse_exif_datetime(value):
    if not value:
        return None
    if isinstance(value, bytes):
        value = value.decode("utf-8", "ignore")
    text = str(value).strip().strip("\x00").strip()[:19]
    for fmt in ("%Y:%m:%d %H:%M:%S", "%Y-%m-%d %H:%M:%S",
                "%Y:%m:%d %H:%M", "%Y-%m-%dT%H:%M:%S"):
        try:
            dt = datetime.strptime(text, fmt)
        except ValueError:
            continue
        if 1900 <= dt.year <= datetime.now().year + 1:
            return dt
    return None


def exif_datetime(path):
    try:
        with Image.open(path) as image:
            exif = image.getexif()
            try:
                ifd = exif.get_ifd(EXIF_IFD)
            except Exception:
                ifd = {}
            for source in (ifd, exif):
                for tag in (TAG_DATE_TIME_ORIGINAL, TAG_DATE_TIME_DIGITIZED, TAG_DATE_TIME):
                    dt = _parse_exif_datetime(source.get(tag))
                    if dt:
                        return dt
    except Exception:
        pass
    return None


def collect_photos(root, recursive):
    walker = root.rglob("*") if recursive else root.iterdir()
    return sorted(
        p for p in walker
        if p.is_file()
        and p.suffix.lower() in PHOTO_EXTENSIONS
        and not p.name.startswith(".")
    )


def build_plan(files, use_mtime, width):
    entries = []
    for path in files:
        taken = None if use_mtime else exif_datetime(path)
        source = "EXIF"
        if taken is None:
            taken = datetime.fromtimestamp(path.stat().st_mtime)
            source = "file date"
        entries.append({"path": path, "taken": taken, "source": source})

    entries.sort(key=lambda e: (e["taken"], e["path"].name.lower()))

    # Names of files we keep as-is must not be handed out to anyone else.
    reserved = {e["path"].name.lower() for e in entries
                if ALREADY_RENAMED.match(e["path"].stem)}

    plan, skipped, counters = [], [], {}
    for entry in entries:
        path = entry["path"]
        if ALREADY_RENAMED.match(path.stem):
            skipped.append(path)
            continue

        day = entry["taken"].strftime("%Y-%m-%d")
        number = counters.get(day, 0)
        while True:
            number += 1
            target = path.with_name(f"{day}_{number:0{width}d}{path.suffix.lower()}")
            if target.name.lower() not in reserved:
                break
        counters[day] = number
        reserved.add(target.name.lower())

        if target.name == path.name:
            skipped.append(path)
        else:
            plan.append((path, target, entry))

    return plan, skipped


def apply_plan(plan):
    # Phase 1: move everything to temporary names so swaps don't collide.
    moved = []
    try:
        for i, (src, _dst, _entry) in enumerate(plan):
            tmp = src.with_name(f".__rename_tmp_{i}__{src.name}")
            src.rename(tmp)
            moved.append((tmp, src))
    except OSError:
        for tmp, src in reversed(moved):
            tmp.rename(src)
        raise

    # Phase 2: temporary name -> final name.
    for (tmp, src), (_src, dst, _entry) in zip(moved, plan):
        try:
            tmp.rename(dst)
        except OSError as exc:
            print(f"!! could not rename {src.name} -> {dst.name}: {exc}", file=sys.stderr)


def main():
    parser = argparse.ArgumentParser(description="Rename photos to their capture date.")
    parser.add_argument("folder", nargs="?", default=".", help="folder to scan (default: .)")
    parser.add_argument("--apply", action="store_true", help="actually rename (default is a dry run)")
    parser.add_argument("--mtime", action="store_true", help="use file modification time instead of EXIF")
    parser.add_argument("-r", "--recursive", action="store_true", help="include subfolders")
    parser.add_argument("--width", type=int, default=3, help="digits in the counter (default: 3)")
    args = parser.parse_args()

    root = Path(args.folder).expanduser()
    if not root.is_dir():
        parser.error(f"not a folder: {root}")

    files = collect_photos(root, args.recursive)
    if not files:
        print("No photos found.")
        return 0

    plan, skipped = build_plan(files, args.mtime, args.width)

    for src, dst, entry in plan:
        print(f"{src.name}  ->  {dst.name}    [{entry['taken']:%Y-%m-%d %H:%M}, {entry['source']}]")

    print(f"\n{len(plan)} to rename, {len(skipped)} already correctly named/unchanged.")

    if not args.apply:
        print("DRY RUN - nothing changed. Re-run with --apply to rename.")
        return 0

    apply_plan(plan)
    print("Done.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
```

Usage:

```bash
pip install Pillow            # plus: pip install pillow-heif   for .heic
python rename_photos_by_date.py .               # preview
python rename_photos_by_date.py . --apply       # rename
```

Details worth knowing:

- **Counter per day**: `2024-05-12_001.jpg`, `_002.jpg`, … restarting on each new date. Files are numbered chronologically by capture time.
- **Collisions**: existing files that already match the pattern keep their names; the script skips over any name already taken. Renames happen in two phases (temp names first), so two photos swapping names can't overwrite each other.
- **Safe to re-run**: photos already named `YYYY-MM-DD_NNN.ext` are left alone.
- **Fallback**: no EXIF date → file modification time. `--mtime` forces that for everything.
- Hidden files and non-photo extensions are ignored; `-r` includes subfolders.
- RAW formats (`.dng`, `.cr2`, `.nef`) aren't in the list because Pillow can't read their EXIF reliably — using `exiftool` would be the way to handle those.

